import{_ as o,o as e,c as a,ag as s}from"./chunks/framework.B7PviQjB.js";const n="/docs/images/board/facilitate-timer.png",r="/docs/images/board/facilitate-voting-results.png",u=JSON.parse('{"title":"Facilitate a session","description":"Run a live session on a board with a shared timer, dot voting, stamps, follow and spotlight, cursor chat, emotes, and comments.","frontmatter":{"title":"Facilitate a session","description":"Run a live session on a board with a shared timer, dot voting, stamps, follow and spotlight, cursor chat, emotes, and comments.","type":"how-to"},"headers":[],"relativePath":"board/facilitate-a-session.md","filePath":"board/facilitate-a-session.md"}'),i={name:"board/facilitate-a-session.md"};function l(h,t,c,d,m,g){return e(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="facilitate-a-session" tabindex="-1">Facilitate a session <a class="header-anchor" href="#facilitate-a-session" aria-label="Permalink to &quot;Facilitate a session&quot;">​</a></h1><p>Run a live session on a board with a shared timer, dot voting, stamps, follow and spotlight, cursor chat, emotes, and comments.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need <strong>Editor</strong> access and must be signed in. Viewers see the timer, cursors, and chat, but can&#39;t vote, stamp, or comment.</li><li>Invite your team first. See <a href="/docs/collaborate/share.html">Share a document</a>.</li></ul></div><p>The tools for running a session sit together in the top toolbar: <strong>Timer</strong>, <strong>Start voting…</strong>, <strong>Spotlight me</strong>, and <strong>Laser pointer</strong>.</p><h2 id="start-a-shared-timer" tabindex="-1">Start a shared timer <a class="header-anchor" href="#start-a-shared-timer" aria-label="Permalink to &quot;Start a shared timer&quot;">​</a></h2><ol><li>Click <strong>Timer</strong> (the stopwatch icon) in the top toolbar.</li><li>Enter the number of minutes, from 1 to 99. The default is 5.</li><li>Click <strong>Start</strong>.</li></ol><p>Everyone on the board, viewers included, sees the countdown in the top-left corner of the canvas. At zero it shows <strong>Time&#39;s up</strong>. While it runs, open <strong>Timer</strong> again to <strong>Pause</strong>, <strong>Resume</strong>, add a minute (<strong>+1m</strong>), or reset it (the circular arrow).</p><p><img src="'+n+'" alt="Running timer popover with Pause, +1m, and reset below the top toolbar, and the countdown chip in the canvas corner"></p><h2 id="run-a-dot-vote" tabindex="-1">Run a dot vote <a class="header-anchor" href="#run-a-dot-vote" aria-label="Permalink to &quot;Run a dot vote&quot;">​</a></h2><ol><li>Click <strong>Start voting…</strong> (the checklist icon) in the top toolbar.</li><li>Under <strong>What are we voting on?</strong>, type the question.</li><li>Set <strong>Votes per person</strong>, from 1 to 10. The default is 3.</li><li>Leave <strong>Only sticky notes</strong> on to allow votes only on sticky notes, or turn it off to allow votes on any item.</li><li>Click <strong>Start</strong>. A voting card opens at the top of the canvas, and your pointer becomes the vote tool.</li><li>Click an item to vote on it. Click your own dot to take the vote back.</li><li>Click <strong>Done</strong> when you finish. To vote again, click <strong>Change my votes</strong>.</li></ol><p>While voting is open, you see only your own votes. The card shows how many people are voting and how many are done. The stamp button in the tool dock becomes <strong>Vote</strong> and shows how many votes you have left. The checklist button in the top toolbar stays highlighted and reads <strong>Voting in progress</strong>; if you switched to another tool, click it to pick up the vote tool again.</p><p>The person who started the vote clicks <strong>End voting</strong>. A <strong>Results</strong> card lists the ten items with the most votes. Click a row to jump to that item. Click <strong>Clear results</strong> to close it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Votes are hidden in the app only. Anyone with access to the board can read them from the board&#39;s data.</p></div><p><img src="'+r+'" alt="Results card listing three sticky notes ranked by vote count"></p><h2 id="stamp-items" tabindex="-1">Stamp items <a class="header-anchor" href="#stamp-items" aria-label="Permalink to &quot;Stamp items&quot;">​</a></h2><ol><li>In the tool dock, click the arrow next to the stamp button (<strong>Stamps</strong>) and pick <strong>+1</strong>, <strong>Heart</strong>, <strong>Star</strong>, <strong>Question</strong>, <strong>Check</strong>, or <strong>Cross</strong>.</li><li>Click an item to stamp it. Click your stamp again to remove it.</li><li>Press <code>Escape</code> or click <strong>Select</strong> when you finish.</li></ol><p>Each stamp is a colored sticker with the stamper&#39;s initial. Stamps are saved on the board, and everyone sees them. While a vote is open and you haven&#39;t clicked <strong>Done</strong>, the stamp tool casts votes instead of stamps.</p><h2 id="follow-a-teammate" tabindex="-1">Follow a teammate <a class="header-anchor" href="#follow-a-teammate" aria-label="Permalink to &quot;Follow a teammate&quot;">​</a></h2><p>Click a teammate&#39;s avatar in the header. Your view follows theirs as they pan and zoom, and a banner reads <strong>Following</strong> <em>name</em> <strong>— Esc to stop</strong>. Press <code>Escape</code>, or pan or zoom yourself, to stop.</p><p>If the teammate has no view to share yet, the board jumps to their cursor instead.</p><h2 id="bring-everyone-to-your-view" tabindex="-1">Bring everyone to your view <a class="header-anchor" href="#bring-everyone-to-your-view" aria-label="Permalink to &quot;Bring everyone to your view&quot;">​</a></h2><p>Click <strong>Spotlight me</strong> (the target icon) in the top toolbar. Everyone else on the board follows your view, and their banner says you are spotlighting. Click it again to stop. Anyone can press <code>Escape</code> to stop following you.</p><h2 id="chat-at-your-cursor-and-send-emotes" tabindex="-1">Chat at your cursor and send emotes <a class="header-anchor" href="#chat-at-your-cursor-and-send-emotes" aria-label="Permalink to &quot;Chat at your cursor and send emotes&quot;">​</a></h2><ul><li><strong>Cursor chat</strong>: press <code>/</code>, type a message of up to 140 characters, and press <code>Enter</code>. It appears next to your cursor on everyone&#39;s screen and fades after 4 seconds. Press <code>Escape</code> to clear it at once.</li><li><strong>Emotes</strong>: press <code>E</code>, then click an emoji or press <code>1</code> to <code>6</code>. It bursts at your pointer for everyone.</li></ul><p>Both keys work only when nothing is selected. Nothing is saved to the board.</p><h2 id="comment-on-a-board" tabindex="-1">Comment on a board <a class="header-anchor" href="#comment-on-a-board" aria-label="Permalink to &quot;Comment on a board&quot;">​</a></h2><ol><li>Select an item and press <code>⌘+Option+M</code> / <code>Ctrl+Alt+M</code>. Or click <strong>Comment</strong> in the tool dock and click an item or an empty spot.</li><li>Type your comment and click <strong>Comment</strong>.</li></ol><p>You can also right-click an item or empty canvas and select <strong>Comment</strong>. To see every thread, click the comments button (<strong>Show comments</strong>) in the header. See <a href="/docs/collaborate/comments.html">Comments and mentions</a>.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><ul><li><strong>Timer</strong>, <strong>Start voting…</strong>, <strong>Spotlight me</strong>, and <strong>Laser pointer</strong> fold into one <strong>Facilitate</strong> button (the people icon) in the top toolbar when nothing is selected. Tap it to open them. It is highlighted while one of them is on.</li><li>The stamp and <strong>Comment</strong> tools are under <strong>More tools</strong> (the ⋯ button) in the tool dock.</li><li>The header hides teammates&#39; avatars, so you can&#39;t start following from a phone. You still follow someone who spotlights.</li><li>Cursor chat and emotes need a keyboard.</li><li>To see every thread, open the header&#39;s <strong>More</strong> menu (the ⋮ button) and select <strong>Comments</strong>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/board/run-a-retro.html">Run a retro on a board</a> for a full session from start to finish.</li><li><a href="/docs/collaborate/edit-together.html">Edit together</a> for cursors and live changes.</li><li><a href="/docs/board/draw.html#point-with-the-laser">Draw</a> to point at things with the laser.</li></ul>',32)])])}const b=o(i,[["render",l]]);export{u as __pageData,b as default};
